#include <iostream>
#include <string>
#include <vector>
#include <set>
#include <array>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
using std::string;
using std::pair;
using std::vector;
using std::set;
using std::min;
using std::max;
using std::array;
#include <atcoder/all>


typedef long long ll;
typedef pair<ll, ll> P;

vector<ll> solve (const ll n, const vector<ll> &a) {
	vector<ll> ans(n+1, 0);

	vector<P> asort(n);
	for (ll i = 0; i < n; i++) {
		asort[i] = {a[i], i};
	}
	sort(asort.begin(), asort.end());

	array<vector<ll>, 3> integral;

	integral[0].resize(n+3);
	for (ll i = 0; i <= n+2; i++) {
		integral[0][i] = 0;
	}
	set<ll> used = {-1, n};
	for (ll i = n-1; i >= 0; i--) {
		ll val = asort[i].first;
		ll idx = asort[i].second;

		auto itgeq = used.lower_bound(idx);
		auto itle = itgeq; --itle;

		// how many elements (on left/right) can a[idx] absorb as a maximum
		ll r = *itgeq - idx - 1;
		ll l = idx - *itle - 1;

		ll xmin = min(l, r), xmax = max(l, r);

		// ans[0 < i <= 1+min] <- i
		// ans[1+min < i <= 1+max] <- 1+min
		// ans[1+max < i <= 1+min+max] <- 1+min - (i - (1+max))
		// ans[1+min+max < i] <- 0

		// ans'[0 < i <= 1+min] <- +1
		// ans'[1+min < i <= 1+max] <- 0
		// ans'[1+max < i <= 1+min+max] <- -1
		// ans'[1+min+max < i] <- 0

		// ans''[1] <- +1
		// ans''[1+min+1] <- -1
		// ans''[1+max+1] <- -1
		// ans''[1+min+max+1] <- +1
		integral[0][1            ] += val * (+1);
		integral[0][1+xmin+1     ] += val * (-1);
		integral[0][1+xmax+1     ] += val * (-1);
		integral[0][1+xmin+xmax+2] += val * (+1);

		used.insert(idx);
	}
	for (ll order = 1; order <= 2; order++) {
		integral[order].resize(n+3);
		integral[order][0] = 0;
		for (ll i = 1; i <= n+2; i++) {
			integral[order][i] = integral[order][i-1] + integral[order-1][i];
		}
	}

	for (ll i = 1; i <= n; i++) {
		ans[i] = integral[2][i];
	}


	return ans;
}


int main (void) {
	ll n;
	cin >> n;
	vector<ll> a(n);
	for (ll i = 0; i < n; i++) {
		cin >> a[i];
	}
	vector<ll> anslist = solve(n, a);
	for (ll i = 1; i <= n; i++) {
		cout << anslist[i] << "\n";
	}


	return 0;
}

struct S{
	int val_sum, index_sum, len;
};

struct F{
	int a,b;
};

S e(){return S{0,0,0};}
S op(S x,S y){
	return S{x.val_sum + y.val_sum,
		 x.index_sum + y.index_sum,
		 x.len + y.len};
}

F id(){return F{0,0};}
F composition(F f,F g){return F{f.a+g.a, f.b+g.b};}

S mapping(F f,S x){
	return S{x.val_sum + f.a*x.index_sum + f.b*x.len,
		 x.index_sum,
		 x.len};
}
